scripts.obsc_build.py:
# rev4: rebuild obsc.json (same circ() as rev2 cycle1_obsc.py; skyfield 1.55 + DE421), station coords from IAGA-2002 headers
import sys,json,glob; sys.path.insert(0,'/tmp/ecl2')
import os; os.chdir('/tmp/ecl')
from cycle1_obsc import circ
def hdr(s):
    for fn in sorted(glob.glob(f'/tmp/ecl/day/{s}_2026-08-12.txt'))+sorted(glob.glob(f'/tmp/ecl2/ctl/{s}_2026-08-12.txt')):
        lat=lon=el=None
        for l in open(fn):
            if 'Geodetic Latitude' in l: lat=float(l.split()[2])
            if 'Geodetic Longitude' in l: lon=float(l.split()[2]); lon=lon-360 if lon>180 else lon
            if l.strip().startswith('Elevation'): el=float(l.split()[1])
            if l.startswith('DATE'): break
        return lat,lon,el
O={}
for s in ['EBR','SPT','ESK','LER','HAD','NGK','GUI','CLF','ASC','KOU','HER']:
    lat,lon,el=hdr(s); c=circ(lat,lon); c.update(lat=lat,lon=lon); O[s]=c
    print(s,lat,lon,{k:v for k,v in c.items() if k not in('series','sun_alt','mins')})
json.dump(O,open('/tmp/ecl/obsc.json','w'))

scripts.rev4_profile.py:
# rev4 (EXP-687 cycle-4 prep). NOT PRE-REGISTERED. Joint-amplitude test of the dome formula with CONTROL-DAY calibration (C3-2),
# alternative standard-physics/null profiles (C3-3f; HNOTE-ANALYST-EXP687-REV4 item 1), single null-set convention (C3-10).
# Null set (all statistics in this file): the days on which all 8 stations are evaluable and max Kp(12-24 UT) <= 3; for the day being
# evaluated the null excludes that day and the eclipse day (identical to rev3_profile_ctl.py). Inputs as rev3 (lib.py, rev3_fits.jfit).
import sys,json,hashlib; sys.path.insert(0,'/tmp/ecl2'); sys.path.insert(0,'/tmp/ecl3')
import numpy as np
from lib import *
from tests import lag
from rev3_fits import jfit
FR=json.load(open('/tmp/ecl3/frozen_b2m001.json'))
ST=['EBR','SPT','CLF','GUI','NGK','HAD','ESK','LER']; INB=['EBR','SPT','CLF','GUI','NGK']
BOU=-10.9; KAPPA=1.672
def sq_level(s,comp):
    """quiet-day mean (Q days) at the station's max-coverage minute minus its mean over local 00-03 h (crude local Sq proxy)"""
    d=load(s); b,_=base(d,comp,Q); c1,tm,c4=contacts(s)
    off=int(round(-O[s]['lon']/15*60)); night=(np.arange(0,180)+off)%1440
    return float(b[tm]-np.nanmean(b[night]))
SUNALT={s:O[s]['sun_alt_at_max'] for s in ST}
def profiles(comp):
    sq={s:sq_level(s,comp) for s in ST}
    return {'dome_FSF':{s:FR[s]['fsf'] for s in ST},
            'binary_maglat_0p3':{s:(1.0 if s in INB else 0.3) for s in ST},
            'flat':{s:1.0 for s in ST},
            'sin_solar_elevation':{s:float(np.sin(np.radians(SUNALT[s]))) for s in ST},
            'sq_proxy_local':sq}, sq
def wls(R_,S_,P,keys):
    x=np.array([P[s] for s in keys]); y=np.array([R_[s] for s in keys]); w=1/np.array([S_[s] for s in keys])**2
    k=np.sum(w*x*y)/np.sum(w*x*x); se=1/np.sqrt(np.sum(w*x*x)); chi=float(np.sum(w*(y-k*x)**2))
    return float(k),float(se),chi
def station_fits(comp,tau,quad,shift=0):
    A={}
    for s in ST:
        d=load(s); ob=obsc_series(s)
        tp=lag(ob,tau); tp=tp/tp.max(); tp=np.roll(tp,shift)
        c1,tm,c4=[x+shift for x in contacts(s)]; w=np.arange(c1-60,c4+61)
        if w.max()>=1440 or w.min()<0: return None
        A[s]={}
        for day in sorted(d):
            b,_=base(d,comp,Q,exclude=day); a=jfit(d[day][comp]-b,w,tp,quad)
            if np.isfinite(a): A[s][day]=a
    return A
def per_day(A,covin):
    days=sorted(set.intersection(*[set(A[s]) for s in ST]))
    ok=[dd for dd in days if dd==EVD or max(KPD[dd][4:8])<=3.0]
    out={}
    for day in ok:
        R_={};S_={}
        for s in ST:
            nul=np.array([A[s][x] for x in ok if x not in (day,EVD)]); mu,sd=nul.mean(),nul.std(ddof=1)
            cov=FR[s]['cov'] if covin=='dome_coverage' else O[s]['max_obsc']
            den=BOU*cov; R_[s]=(A[s][day]-mu)/den; S_[s]=sd/abs(den)
        out[day]=(R_,S_)
    return out
if __name__=='__main__':
    res={'_meta':dict(script='rev4_profile.py',preregistered=False,
        null_set='all-8-evaluable days with max Kp(12-24 UT)<=3; per evaluated day the null excludes that day and the eclipse day (same as rev3_profile_ctl.py). This is the single convention for every k in rev4 (C3-10).',
        k_definition='residual_s = (A_s - null_mean_s)/(-10.9 x coverage_s); WLS fit residual = k x profile_s with weights 1/(null_sd_s/|-10.9 cov_s|)^2. For profile dome_FSF, k=1 is the dome formula at the -10.9 BOU baseline and k=1.672 is the x1.672-corrected specification.',
        control_calibration='k is computed identically on every control day; the control-day SD of k is used instead of the WLS se (which assumes independent station noise) to express the event k distance from 0, 1 and 1.672.',
        profiles='dome_FSF (frozen file per-station FSF); binary_maglat_0p3 (our WIN-010 registered stand-in, NGK in-band); flat (1 at every station); sin_solar_elevation (sin of Sun elevation at local maximum, skyfield DE421); sq_proxy_local (quiet-day mean of the same component at local maximum minus its local 00-03 h mean - a crude first-order Sq-weakening expectation with station-dependent SIGN; post hoc).')}
    sqtab={}
    for comp in ['Z','H']:
        P,sq=profiles(comp); sqtab[comp]={s:round(v,2) for s,v in sq.items()}
        for tau in (0,30):
            for quad in (False,True):
                A=station_fits(comp,tau,quad)
                for covin in ('dome_coverage','ephemeris_obscuration'):
                    D=per_day(A,covin); ctl=[x for x in D if x!=EVD]
                    rows={}
                    for day,(R_,S_) in D.items():
                        rows[day]={pn:wls(R_,S_,pp,ST) for pn,pp in P.items()}
                    kev,seev,_=rows[EVD]['dome_FSF']; kc=np.array([rows[x]['dome_FSF'][0] for x in ctl])
                    sdc=float(kc.std(ddof=1)); mc=float(kc.mean())
                    chi_ev={pn:round(v[2],2) for pn,v in rows[EVD].items()}
                    kz_ev={pn:round(v[0]/v[1],2) for pn,v in rows[EVD].items()}
                    best_ctl={pn:int(sum(min(rows[x],key=lambda q:rows[x][q][2])==pn for x in ctl)) for pn in P}
                    rec=dict(n_control=len(ctl),
                        event=dict(k_FSF=round(kev,3),k_FSF_se_wls=round(seev,3),
                                   k_per_profile={pn:round(v[0],3) for pn,v in rows[EVD].items()},kz_per_profile=kz_ev,chi2_per_profile=chi_ev,
                                   best_profile=min(chi_ev,key=chi_ev.get)),
                        control_k_FSF=dict(mean=round(mc,3),sd=round(sdc,3),min=round(float(kc.min()),3),max=round(float(kc.max()),3),
                                   n_ge_event=int(np.sum(kc>=kev)),values={x:round(rows[x]['dome_FSF'][0],3) for x in ctl}),
                        formula_rejection=dict(
                            wls_se_units=dict(k_minus_1=round((1-kev)/seev,2),k_minus_1p672=round((KAPPA-kev)/seev,2),k_vs_0=round(kev/seev,2)),
                            control_sd_units=dict(k_minus_1=round((1-kev)/sdc,2),k_minus_1p672=round((KAPPA-kev)/sdc,2),
                                                  event_vs_control_mean=round((kev-mc)/sdc,2)),
                            control_days_with_k_ge_1=int(np.sum(kc>=1.0))),
                        control_best_profile_counts=best_ctl,
                        control_chi2_FSF_minus_flat_ge_event=int(sum((rows[x]['flat'][2]-rows[x]['dome_FSF'][2])>=(rows[EVD]['flat'][2]-rows[EVD]['dome_FSF'][2]) for x in ctl)),
                        event_residuals={s:round(D[EVD][0][s],3) for s in ST},event_residual_sd={s:round(D[EVD][1][s],3) for s in ST})
                    key=f"{comp}|obsc_tau{tau}|{'quad' if quad else 'lin'}|{covin}|alpha1.0|all8"
                    res[key]=rec
                    print(key,'k=%.3f se=%.3f ctl mean %.3f sd %.3f | (1-k)/sdc %.2f (1.672-k)/sdc %.2f | chi2 %s | ctl_best %s'%(kev,seev,mc,sdc,(1-kev)/sdc,(KAPPA-kev)/sdc,chi_ev,best_ctl),flush=True)
    res['sq_proxy_levels_nT']=sqtab
    # time shifts with control-day calibration (C3-3): Z, tau0, dome coverage
    ECL_UNION=(hm('17:02'),hm('19:45')); G4=hm('21:01')
    sh={}
    for quad in (False,True):
        for shift in [-360,-300,-240,-180,-120,0,120,180]:
            A=station_fits('Z',0,quad,shift)
            if A is None: continue
            D=per_day(A,'dome_coverage'); ctl=[x for x in D if x!=EVD]
            def kz(day,pn='dome_FSF'):
                R_,S_=D[day]; P,_=profiles('Z'); k,se,chi=wls(R_,S_,P[pn],ST); return k/se,chi
            ev=kz(EVD); cz=np.array([kz(x)[0] for x in ctl])
            wins=[(contacts(s)[0]-60+shift,contacts(s)[2]+60+shift) for s in ST]
            overlap_own=[s for s,(a,b) in zip(ST,wins) if a<=contacts(s)[2] and b>=contacts(s)[0]]
            overlap_any=any(a<=ECL_UNION[1] and b>=ECL_UNION[0] for a,b in wins)
            sh[f"Z|{'quad' if quad else 'lin'}|shift{shift:+d}min"]=dict(event_FSF_kz=round(ev[0],2),event_FSF_chi2=round(ev[1],2),
                control_n=len(ctl),control_abs_kz_ge_event=int(np.sum(np.abs(cz)>=abs(ev[0]))),control_kz_sd=round(float(cz.std(ddof=1)),2),
                window_range_ut=[fmt(min(a for a,b in wins)),fmt(max(b for a,b in wins))],
                stations_whose_own_eclipse_overlaps_window=overlap_own,overlaps_any_station_eclipse_1702_1945=bool(overlap_any),
                contains_dome_global_C4_2101=bool(any(a<=G4<=b for a,b in wins)),
                clean=bool((not overlap_any) and not any(a<=G4<=b for a,b in wins)))
            print('shift',quad,shift,sh[f"Z|{'quad' if quad else 'lin'}|shift{shift:+d}min"],flush=True)
    res['time_shift_calibrated']=sh
    json.dump(res,open('/tmp/ecl4/rev4_profile.json','w'),indent=1)
    print('sha256',hashlib.sha256(open('/tmp/ecl4/rev4_profile.json','rb').read()).hexdigest())

scripts.rev4_lag_injection.py:
# rev4 (C3-4). NOT PRE-REGISTERED. Mismatch-injection test: does the trend model (linear vs quadratic) absorb an eclipse response whose
# lag differs from the fitted template? Inject a true response = A x lag(obscuration, L)/peak (first-order exponential relaxation, L = 0/15/30/60 min)
# into the REAL Z deviation of every null day, fit with the tau-0 and tau-30 obscuration templates under linear and quadratic trends,
# recovered fraction = (fit_with_injection - fit_without)/A, averaged over null days. Linear least squares => independent of A.
import sys,json,hashlib; sys.path.insert(0,'/tmp/ecl2'); sys.path.insert(0,'/tmp/ecl3')
import numpy as np
from lib import *
from tests import lag
from rev3_fits import jfit
ST=['EBR','SPT','HAD','CLF','NGK','ESK','LER','GUI']; PRIO=['EBR','SPT','HAD','CLF','NGK','ESK']
A0=-10.0
out={'_meta':dict(script='rev4_lag_injection.py',preregistered=False,injection_amplitude_nT=A0,
     null_days='days with max Kp(12-24 UT)<=3 excluding the eclipse day; baseline leave-one-out as rev3',
     recovered_fraction='mean over null days of (fit(dev + A x true_shape) - fit(dev))/A; true_shape peak-normalised')}
for comp in ['Z','H']:
  for s in ST:
    d=load(s); c1,tm,c4=contacts(s); ob=obsc_series(s); w=np.arange(c1-60,c4+61)
    rec={}
    for tt in (0,30):
        tp=lag(ob,tt); tp=tp/tp.max()
        for quad in (False,True):
            for L in (0,15,30,60):
                tr=lag(ob,L); tr=tr/tr.max(); fr=[]
                for day in sorted(d):
                    if day==EVD or max(KPD[day][4:8])>3.0: continue
                    b,_=base(d,comp,Q,exclude=day); x=d[day][comp]-b
                    a0=jfit(x,w,tp,quad); a1=jfit(x+A0*tr,w,tp,quad)
                    if np.isfinite(a0) and np.isfinite(a1): fr.append((a1-a0)/A0)
                rec[f"template_tau{tt}|{'quad' if quad else 'lin'}|true_lag{L}"]=round(float(np.mean(fr)),3)
    out[f'{comp}|{s}']=rec
summ={}
for comp in ['Z','H']:
  for key in out[f'{comp}|EBR']:
    v=[out[f'{comp}|{s}'][key] for s in PRIO]
    summ[f'{comp}|{key}']=dict(priority_mean=round(float(np.mean(v)),3),priority_min=round(float(np.min(v)),3),priority_max=round(float(np.max(v)),3))
out['summary_priority_stations']=summ
json.dump(out,open('/tmp/ecl4/rev4_lag_injection.json','w'),indent=1)
for k,v in summ.items():
    if k.startswith('Z'): print(k,v)
print('sha256',hashlib.sha256(open('/tmp/ecl4/rev4_lag_injection.json','rb').read()).hexdigest())

scripts.rev4_power.py:
# rev4 (C3-1, C3-5). NOT PRE-REGISTERED. Power at the dome formula's x1.672-corrected per-station amplitudes (the dome's own
# pre-event specification: monitor/baseline/03-predictions.txt:75 and 05-model.txt:475) for every rev3 template (obscuration tau 0/15/30/60;
# contact-phase local and global, sigma 3/5/10/20/30 min) and both trend models; plus a summary over pulse widths of the rev3 BOU-baseline
# and -17 nT powers (read from rev3_fits.json, unchanged) so the contact-phase claim is stated per pulse width (C3-5).
import sys,json,hashlib; sys.path.insert(0,'/tmp/ecl2'); sys.path.insert(0,'/tmp/ecl3')
import numpy as np
from lib import *
import rev3_fits as R3
FR=json.load(open('/tmp/ecl3/frozen_b2m001.json')); R=json.load(open('/tmp/ecl3/rev3_fits.json'))
KAPPA=1.672; KSIG=[2,3,5]
ST=['EBR','SPT','HAD','CLF','NGK','ESK','LER','GUI']; PRIO=['EBR','SPT','HAD','CLF','NGK','ESK']
out={'_meta':dict(script='rev4_power.py',preregistered=False,amplitudes='formula_BOU1672_domecov = -10.9 x 1.672 x dome coverage x FSF (= -18.22 x cov x FSF, the PRED-095 card arithmetic); formula_BOU1672_ephemcov uses ephemeris obscuration',
     power='as rev3: fraction of null days where fit(real deviation + A x template) < null_mean - k x null_sd')}
for comp in ['Z','H']:
  for s in ST:
    d=load(s); fr=FR[s]; amps={'formula_BOU1672_domecov':-10.9*KAPPA*fr['cov']*fr['fsf'],'formula_BOU1672_ephemcov':-10.9*KAPPA*O[s]['max_obsc']*fr['fsf']}
    rec={}
    for name,(tp,w) in R3.templates(s).items():
        for quad in (False,True):
            nul=[];devs=[]
            for day in sorted(d):
                b,_=base(d,comp,Q,exclude=day); x=d[day][comp]-b; a=R3.jfit(x,w,tp,quad)
                if not np.isfinite(a) or day==EVD: continue
                if max(KPD[day][4:8])<=3.0: nul.append(a); devs.append(x)
            if len(nul)<8: continue
            mu,sd=float(np.mean(nul)),float(np.std(nul,ddof=1))
            key=f"{name}|{'quad' if quad else 'lin'}"
            ev=R[f'{comp}|{s}'].get(key,{}).get('A')
            pw={}
            for an,av in amps.items():
                fits=np.array([R3.jfit(x+av*tp,w,tp,quad) for x in devs])
                pw[an]=dict(amp_nT=round(av,2),**{f'power_{k}sigma':round(float(np.mean(fits<mu-k*sd)),2) for k in KSIG},
                            consistency_z=(round((ev-mu-av)/sd,2) if ev is not None else None))
            rec[key]=pw
    out[f'{comp}|{s}']=rec
# per-pulse-width summary over priority stations (Z), 3 sigma
summ={}
for fam in ['c14_local','c14_global']:
  for sg in [3,5,10,20,30]:
    for tr in ['lin','quad']:
      key=f'{fam}_sig{sg}|{tr}'
      row={}
      for an in ['PRED095_-17','formula_BOU_domecov']:
          row[an]={s:R[f'Z|{s}'][key]['injection_power'][an]['power_3sigma'] for s in PRIO}
      row['formula_BOU1672_domecov']={s:out[f'Z|{s}'][key]['formula_BOU1672_domecov']['power_3sigma'] for s in PRIO}
      row['min_over_priority']={an:min(v.values()) for an,v in row.items()}
      row['nonpriority_LER_GUI_BOU_power']={s:R[f'Z|{s}'][key]['injection_power']['formula_BOU_domecov']['power_3sigma'] for s in ['LER','GUI'] if key in R[f'Z|{s}']}
      summ[key]=row
for t in [0,15,30,60]:
  for tr in ['lin','quad']:
    key=f'obsc_tau{t}|{tr}'
    row={an:{s:R[f'Z|{s}'][key]['injection_power'][an]['power_3sigma'] for s in PRIO} for an in ['PRED095_-17','formula_BOU_domecov']}
    row['formula_BOU1672_domecov']={s:out[f'Z|{s}'][key]['formula_BOU1672_domecov']['power_3sigma'] for s in PRIO}
    row['consistency_z_BOU1672']={s:out[f'Z|{s}'][key]['formula_BOU1672_domecov']['consistency_z'] for s in PRIO}
    row['min_over_priority']={an:min(v.values()) for an,v in row.items() if an!='consistency_z_BOU1672'}
    summ[key]=row
out['summary_Z_priority_3sigma']=summ
json.dump(out,open('/tmp/ecl4/rev4_power.json','w'),indent=1)
for k,v in summ.items(): print(k,v['min_over_priority'],v.get('consistency_z_BOU1672',''), v.get('nonpriority_LER_GUI_BOU_power',''))
print('sha256',hashlib.sha256(open('/tmp/ecl4/rev4_power.json','rb').read()).hexdigest())

scripts.rev4_two_sided.py:
# rev4 (HNOTE item 1). NOT PRE-REGISTERED. Two-sided read of every rev3 obscuration-template fit (Z and H, 8 stations, tau 0-60,
# linear/quadratic): does any station show a significant POSITIVE eclipse-attributable deviation, as a position-dependent-sign
# (station south vs north of the shadow / of the Sq focus) standard-physics response would allow? Reads rev3_fits.json (unchanged) and
# the rev4 local Sq-proxy levels (rev4_profile.json).
import json,hashlib
R=json.load(open('/tmp/ecl3/rev3_fits.json')); P=json.load(open('/tmp/ecl4/rev4_profile.json'))
ST=['EBR','SPT','CLF','GUI','NGK','HAD','ESK','LER']
out={'_meta':dict(script='rev4_two_sided.py',preregistered=False,z='(A - null_mean)/null_sd from rev3_fits.json')}
for comp in ['Z','H']:
    tab={}
    for s in ST:
        zs={k:v['z'] for k,v in R[f'{comp}|{s}'].items() if k.startswith('obsc_')}
        tab[s]=dict(sq_proxy_level_nT=P['sq_proxy_levels_nT'][comp][s],expected_sign_if_sq_weakening=('-' if P['sq_proxy_levels_nT'][comp][s]>0 else '+'),
                    z_by_variant=zs,max_z=max(zs.values()),min_z=min(zs.values()),
                    n_variants_z_ge_plus3=sum(v>=3 for v in zs.values()),n_variants_z_le_minus3=sum(v<=-3 for v in zs.values()),
                    observed_sign_majority=('-' if sum(v<0 for v in zs.values())>len(zs)/2 else '+'))
    out[comp]=tab
    for s,v in tab.items(): print(comp,s,v['sq_proxy_level_nT'],v['expected_sign_if_sq_weakening'],v['observed_sign_majority'],v['min_z'],v['max_z'],v['n_variants_z_ge_plus3'],v['n_variants_z_le_minus3'])
json.dump(out,open('/tmp/ecl4/rev4_two_sided.json','w'),indent=1)
print('sha256',hashlib.sha256(open('/tmp/ecl4/rev4_two_sided.json','rb').read()).hexdigest())

scripts.rev4_inputs_manifest.py:
# rev4 (C3-8). Input-file manifest: sha256 + IAGA-2002 'Data Type' + 'Publication Date' of every input file used by rev2-rev4 scripts,
# fetched 2026-10-04 with the request shape in _meta.gin_url_template. Lets a third party detect any later change (e.g. quasi-definitive
# -> definitive replacement) before or after an OTS stamp.
import glob,hashlib,json,os
def sha(fn): return hashlib.sha256(open(fn,'rb').read()).hexdigest()
def hdr(fn):
    dt=pd=None
    with open(fn,errors='replace') as f:
        for l in f:
            if 'Data Type' in l: dt=l.split('Type',1)[1].strip(' |\n')
            if 'Publication Date' in l: pd=l.split('Date',1)[1].strip(' |\n')
            if l.startswith('DATE'): break
    return dt,pd
groups={'stations_2026_07_13_to_08_12':sorted(glob.glob('/tmp/ecl/day/*.txt')),'control_stations_ASC_KOU_HER':sorted(glob.glob('/tmp/ecl2/ctl/*.txt')),
        'BOU_quiet_test':sorted(glob.glob('/tmp/ecl4/bou/BOU_*.txt'))}
out={'_meta':dict(script='rev4_inputs_manifest.py',fetched_at_utc='2026-10-04',
     gin_url_template='https://imag-data.bgs.ac.uk/GIN_V1/GINServices?Request=GetData&format=iaga2002&testObsys=0&observatoryIagaCode=<IAGA>&samplesPerDay=minute&dataStartDate=<YYYY-MM-DD>&dataDuration=1&publicationState=best-avail&orientation=native',
     definitive_check='publicationState=definitive for EBR/HAD/NGK 2026-08-12 returns a file whose header says Definitive but every sample is 99999 (not yet published); no 2026 definitive data were available on 2026-10-04.',
     reproduction_check='rev3_fits.json, rev3_win010_profile.json, rev3_profile_ctl.json and rev3_profile_shift.json were regenerated from these inputs on 2026-10-04 and are byte-identical to the rev3 bundle outputs (same sha256).')}
for g,fs in groups.items():
    rows={}; types={}
    for fn in fs:
        dt,pd=hdr(fn); rows[os.path.basename(fn)]=dict(sha256=sha(fn),data_type=dt,publication_date=pd); types[dt]=types.get(dt,0)+1
    out[g]=dict(n_files=len(fs),data_type_counts=types,files=rows)
for fn in ['/tmp/ecl/kp.json','/tmp/ecl/obsc.json','/tmp/ecl/de421.bsp','/tmp/ecl3/frozen_b2m001.json']:
    out.setdefault('other_inputs',{})[os.path.basename(fn)]=sha(fn)
agg=hashlib.sha256(''.join(sorted(r['sha256'] for g in groups for r in out[g]['files'].values())).encode()).hexdigest()
